{
  "findings": [
    {
      "check_id": "CKV_GCP_10",
      "title": "Overly permissive IAM role (roles/editor) assigned to users",
      "resource": "google_project_iam_binding.trading_platform_admin",
      "severity": "HIGH",
      "explanation": "Assigning 'roles/editor' grants write access to all resources in the project, which violates the principle of least privilege. Users should be granted specific roles required for their tasks instead."
    }
  ],
  "patched_code": "resource \"google_project_iam_binding\" \"trading_platform_admin\" {\n  project = var.project_id\n  # TODO: Replace with a more restrictive role appropriate for traders/admins (e.g., roles/viewer or custom roles)\n  role    = \"roles/viewer\"\n  members = [\n    \"user:trader@${var.organization_domain}\",\n    \"user:admin@${var.organization_domain}\",\n  ]\n}",
  "fix_summary": "Changed the IAM role from 'roles/editor' to 'roles/viewer' to adhere to the principle of least privilege. Note that 'roles/viewer' is read-only; if write access is strictly necessary for these users, a more granular custom role or specific service-level editor role should be defined and used instead."
}
